def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            seen.add((r, c))
            stack = [(r, c)]
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen
                            and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append((color, cells))
    return components

def _l_dimensions(cells):
    points = set(cells)
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    for elbow_r in range(r0, r1 + 1):
        for elbow_c in range(c0, c1 + 1):
            vertical = {(r, elbow_c) for r in range(r0, r1 + 1)}
            horizontal = {(elbow_r, c) for c in range(c0, c1 + 1)}
            if points == vertical | horizontal:
                return r1 - r0 + 1, c1 - c0 + 1
    return None

def transform(grid):
    components = _components(grid)
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    keys = []
    for color, cells in components:
        dimensions = _l_dimensions(cells) if color != background else None
        if dimensions is not None:
            keys.append((len(cells), color, cells, dimensions))
    if not keys:
        return [row[:] for row in grid]
    _, key_color, key_cells, (key_h, key_w) = max(keys, key=lambda item: item[0])
    target_dims = (key_h - 2, key_w - 2)
    key_r = [r for r, c in key_cells]
    key_c = [c for r, c in key_cells]
    targets = []
    for color, cells in components:
        if color == background or cells == key_cells:
            continue
        h = max(r for r, c in cells) - min(r for r, c in cells) + 1
        w = max(c for r, c in cells) - min(c for r, c in cells) + 1
        if (h, w) == target_dims:
            distance = min(abs(r-kr) + abs(c-kc) for r, c in cells for kr, kc in key_cells)
            targets.append((distance, cells))
    if not targets:
        return [row[:] for row in grid]
    # When copies share the inset shape, the one farthest from the key is the target.
    target = max(targets, key=lambda item: item[0])[1]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = key_color
    return out
